223	430	events	211	{"external_id":"insa-lyon-portal-2484","name":"Bal","startDate":"2026-05-09T21:00:10","endDate":"2026-05-10T05:00:29","description":"Le Bal INSA Lyon est une soirée de prestige. C’est un événement incontournable qui réunit les étudiants du campus autour d’une fête élégante et thématique mêlant musique, danse et ambiance festive. Chaque édition se déroule dans un lieu emblématique, avec une mise en scène soignée, des artistes variés et des animations originales. Alliant élégance et convivialité, le Bal INSA Lyon est un moment fort de la vie étudiante, symbole de célébration et de partage au sein du campus.","location":"Double Mixte","geo":{"type":"Point","coordinates":[4.87273,45.78103]},"categories":["Soirée"],"logo_url":"https://logos.bde-insa-lyon.fr/bde/bde.png","website_url":null,"rawData":{"id":2484,"name":"Bal","short_description":"Soirée de prestige pour tous les étudiants du Campus","description":"Le Bal INSA Lyon est une soirée de prestige. C’est un événement incontournable qui réunit les étudiants du campus autour d’une fête élégante et thématique mêlant musique, danse et ambiance festive. Chaque édition se déroule dans un lieu emblématique, avec une mise en scène soignée, des artistes variés et des animations originales. Alliant élégance et convivialité, le Bal INSA Lyon est un moment fort de la vie étudiante, symbole de célébration et de partage au sein du campus.","type":{"id":5,"name":"Soirée","color":"#7b1fa2"},"association":{"id":2,"name":"Bureau des Élèves","acronym":"BdE INSA Lyon"},"location":{"id":86,"name":"Double Mixte","lat":"45.781030","long":"4.872730","is_room":false,"is_cave":false},"begins_at":"2026-05-09T21:00:10","ends_at":"2026-05-10T05:00:29","prices":[],"website_url":"","logo_url":"https://logos.bde-insa-lyon.fr/bde/bde.png","facebook_url":"","external":{}}}	{"external_id":"insa-lyon-portal-2484","name":"Bal","startDate":"2026-05-09T21:00:10","endDate":"2026-05-10T05:00:29","description":"Le Bal INSA Lyon est une s